<?php use App\Services\BookingRules; $total=array_sum($reservationCounts); ?>
<section class="student-home"><header class="student-welcome"><div><p>YOUR CAMPUS RESOURCES</p><h1>Welcome back, <?= esc($student['full_name']??'Student') ?>!</h1><span>Explore campus spaces and equipment, and keep track of your reservations.</span><a class="student-welcome-action" href="<?= site_url('borrower/resources') ?>">Browse resources <span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span></a></div><a class="student-bell" href="<?= site_url('notifications') ?>" aria-label="Open notifications"><span class="material-symbols-outlined" aria-hidden="true">notifications</span></a></header>
<div class="student-overview"><article><span class="material-symbols-outlined" aria-hidden="true">event_note</span><div><small>My reservations</small><strong><?= (int)$total ?></strong></div></article><article><span class="material-symbols-outlined" aria-hidden="true">calendar_month</span><div><small>Upcoming reservations</small><strong><?= (int)$upcomingCount ?></strong></div></article><article><span class="material-symbols-outlined" aria-hidden="true">payments</span><div><small>Payment or review</small><strong><?= (int)$paymentActionCount ?></strong></div></article></div>
<section class="student-home-section"><h2>Quick Actions</h2><div class="student-quick-grid"><?php foreach([['borrower/resources','inventory_2','Browse Resources','Explore spaces and equipment'],['borrower/reservations/new','add_circle','Make a Reservation','Request campus resources'],['borrower/reservations','event_available','My Reservations','Check your requests']] as [$url,$icon,$label,$description]): ?><a class="student-quick-card" href="<?= site_url($url) ?>"><span class="material-symbols-outlined" aria-hidden="true"><?= esc($icon) ?></span><span><strong><?= esc($label) ?></strong><small><?= esc($description) ?></small></span><span class="material-symbols-outlined student-arrow" aria-hidden="true">arrow_forward</span></a><?php endforeach ?></div></section>
<section class="student-home-card"><header><h2>Reservation Overview</h2><a href="<?= site_url('borrower/reservations') ?>">View history</a></header><?php if($total): ?><div class="student-status-bar" aria-label="Reservation status distribution"><?php foreach($reservationCounts as $status=>$count): ?><?php if($count): ?><span class="segment <?= esc($status,'attr') ?>" style="width:<?= esc((string)($count/$total*100),'attr') ?>%" title="<?= esc(ucfirst($status).': '.$count,'attr') ?>"></span><?php endif ?><?php endforeach ?></div><?php else: ?><p class="student-empty">No reservations yet.</p><?php endif ?><ul class="student-status-legend"><?php foreach($reservationCounts as $status=>$count): ?><li><span class="status-dot <?= esc($status,'attr') ?>" aria-hidden="true"></span><?= esc(ucfirst($status)) ?> <strong><?= (int)$count ?></strong></li><?php endforeach ?></ul></section>
<section class="student-home-card"><header><h2>Upcoming Reservations</h2><a href="<?= site_url('borrower/reservations') ?>">View all</a></header><?php if($upcomingReservations): ?><ul class="student-schedule"><?php foreach($upcomingReservations as $reservation): ?><li><span class="material-symbols-outlined" aria-hidden="true">calendar_month</span><div><strong><?= esc($reservation['resources']?:'Reservation #'.$reservation['id']) ?></strong><small>Reservation #<?= (int)$reservation['id'] ?> · <?= esc(BookingRules::display($reservation['start_datetime'])) ?> – <?= esc(BookingRules::display($reservation['end_datetime'])) ?> Manila</small><?php if(!empty($reservation['locations'])): ?><small><?= esc($reservation['locations']) ?></small><?php endif ?></div><span class="status-badge <?= esc($reservation['status'],'attr') ?>"><?= esc(ucfirst($reservation['status'])) ?></span><a href="<?= site_url('borrower/reservations/'.$reservation['id']) ?>">Details</a></li><?php endforeach ?></ul><?php else: ?><p class="student-empty"><span class="material-symbols-outlined" aria-hidden="true">event_available</span>No upcoming reservations. <a href="<?= site_url('borrower/resources') ?>">Browse resources</a></p><?php endif ?></section>
<div class="student-home-grid"><section class="student-home-card"><header><h2>Action Required</h2></header><?php if($paymentActionCount>0): ?><p class="student-action-summary"><?= (int)$paymentActionCount ?> reservation<?= $paymentActionCount===1?'' : 's' ?> requiring payment or review.</p><?php endif ?><?php if($actions): ?><ul class="student-actions-list"><?php foreach(array_slice($actions,0,3) as $action): ?><li><span class="material-symbols-outlined" aria-hidden="true">info</span><div><strong>Reservation #<?= (int)$action['id'] ?></strong><small><?= esc($action['message']) ?></small></div><a class="student-review" href="<?= site_url('borrower/reservations/'.$action['id']) ?>">Review</a></li><?php endforeach ?></ul><?php if(count($actions)>3): ?><a class="student-review-all" href="<?= site_url('borrower/reservations') ?>">Review all reservations</a><?php endif ?><?php else: ?><p class="student-empty"><span class="material-symbols-outlined" aria-hidden="true">check_circle</span>No actions needed right now.</p><?php endif ?></section>
<section class="student-home-card"><header><h2>Recent Activity</h2><a href="<?= site_url('notifications') ?>">View all</a></header><?php if($activity): ?><ul class="student-activity"><?php foreach(array_slice($activity,0,3) as $event): ?><li><span class="material-symbols-outlined" aria-hidden="true"><?= str_starts_with($event['notification_type']??'','payment_')?'payments':'notifications' ?></span><div><strong><?= esc($event['title']) ?></strong><small><?= !empty($event['created_at'])?esc((new DateTimeImmutable($event['created_at'], new DateTimeZone('UTC')))->setTimezone(new DateTimeZone(config('Booking')->timezone))->format('M j, g:i A').' Manila'):'Date unavailable' ?></small></div><?php if(!empty($event['reservation_id'])): ?><a href="<?= site_url('borrower/reservations/'.(int)$event['reservation_id']) ?>">#<?= (int)$event['reservation_id'] ?></a><?php endif ?></li><?php endforeach ?></ul><?php else: ?><p class="student-empty">No recent activity.</p><?php endif ?></section></div></section>
<?= $this->endSection() ?>
